export function wardrobe(g, x, z, len, axis = "x", facing) {
  if (axis !== "x" && axis !== "z") throw new Error(`wardrobe: axis must be x or z, got ${axis}`);
  const front = facing ?? (axis === "x" ? "south" : "west");
  const d = DIRS[front];
  if (!d) throw new Error(`wardrobe: facing must be north, south, east or west, got ${front}`);
  if (axis === "x" ? d[0] !== 0 : d[2] !== 0) throw new Error(`wardrobe: facing ${front} must be across axis ${axis}`);
  const o = newOut();
  const [ax, az] = axis === "x" ? [1, 0] : [0, 1];
  for (let i = 0; i < len; i++) {
    const bx = x + ax * i, bz = z + az * i;
    for (const y of [2, 3]) {
      put(g, o, bx, y, bz, B.block("spruce_planks"));
      put(g, o, bx + d[0], y, bz + d[2], B.trapdoor("spruce", front, "bottom", true));
    }
  }
  return o;
}
export function bed_double(g, x, z, facing, color = "orange") {
  const [dx, , dz] = DIRS[facing] ?? [];
  if (dx === undefined) throw new Error(`bed_double: facing must be north, south, east or west, not ${facing}`);
  const { w, out } = writer(g);
  const [px, pz] = [-dz, dx];                                                // the side, across the bed
  w(x, 2, z, [`${color}_bed`, { facing, part: "foot" }]);
  w(x + dx, 2, z + dz, [`${color}_bed`, { facing, part: "head" }]);
  w(x + 2 * dx, 2, z + 2 * dz, "spruce_planks");
  for (const s of [1, -1]) {
    const nx = x + dx + s * px, nz = z + dz + s * pz;
    w(nx, 2, nz, B.fence("spruce"));
    w(nx, 3, nz, B.slab("birch", "bottom"));
  }
  return out;
}
export function sideboard(g, x, z, len = 2, axis = "x", facing = "south", y = 2) {
  const t = tally();
  const cells = span(0, len - 1).map((i) => (axis === "x" ? [x + i, z] : [x, z + i]));
  for (const [cx, cz] of cells) {
    put(g, t, cx, y, cz, B.trapdoor("birch", facing, "bottom", false));
    put(g, t, cx, y + 1, cz, B.slab("birch", "top"));
  }
  const [mx, mz] = cells[Math.floor((len - 1) / 2)];
  put(g, t, mx, y + 2, mz, B.block("potted_cactus"));
  return t;
}

/**
 * dining_set: a 2x3 table (footprint x..x+1, z..z+2) on four spruce_fence legs at y, with the spruce_slab top at y+1.
 * Six birch_stairs chairs, three each side (west at x-1, east at x+2), seats facing the table. A lantern hangs at
 * (x+1, y+2, z+1) when there is a beam above it.
 */
export function hung_lantern(g, x, z, y = 4) {
  const o = newOut();
  if (g.isAir(x, y + 1, z)) {
    o.skipped.push([x, y, z, "lantern"]);
    o.reason = `no block at y=${y + 1} to hang from`;
    return o;
  }
  put(g, o, x, y, z, B.lantern(true));
  return o;
}

/**
 * Egg chair: seat stairs at (x, 2, z) that the sitter faces along `facing` (the seat's solid back points the other way);
 * an open iron_trapdoor back at the cell behind the seat, y=2 and y=3; one open iron_trapdoor on each side at y=2.
 * The cell in front of the seat is left clear.
 */
 *   ])
 * A single layer may be passed as one array of rows. Characters not in the legend (space, ".") are left as they are.
 * Writes go through g.set, so runParts' lock and palette report apply. Returns the number of blocks placed.
 */
export function layers(g, [x0, y0, z0], legend, rowsOrLayers) {
  const list = typeof rowsOrLayers[0] === "string" ? [rowsOrLayers] : rowsOrLayers;
  let n = 0;
  list.forEach((rows, dy) => rows.forEach((row, dz) => [...row].forEach((ch, dx) => {
    const e = legend[ch];
    if (e == null) return;
    const [block, state, nbt] = Array.isArray(e) ? e : [e];
    g.set(x0 + dx, y0 + dy, z0 + dz, block, state, nbt);
    n++;
  })));
  return n;
}

/**
 * Run a build's parts in order so each part can only ADD to what earlier parts built: a write into a cell an earlier
 * part placed (air included, so no carving) is refused, counted, never thrown, so a later part can't knock holes in
 * a wall. Cells set before runParts (the ground) stay writable: farmland and paths may replace grass. With a palette
 * (palette.json, or its object: { roles: { role: [blocks] }, objects: [blocks] }), every block placed outside it is
 * reported. Prints one line per part, writes the reports to `report` (default parts-report.json; null for none) and
 * returns them.
 *   runParts(g, [["shell", shell.build], ["garden", garden.build]], { palette: "palette.json" })
 */
